        return 0, 0, 0, 0
    try:
        data = json.loads(_read_text(prior_summary))
    except json.JSONDecodeError:
        return 0, 0, 0, 0
    if data.get("schema_version") not in {2, 3}:
        return 0, 0, 0, 0
    prior_rounds = int(data.get("rounds_completed", 0) or 0)
    if prior_rounds >= round_num:
