def _count_rejected_lines(path: Path) -> int:
    if not path.is_file() or not path.stat().st_size:
        return 0
    text = _read_text(path)
    count = len(re.findall(r"^###\s+\[(?:rejected|Code Review)\]\s+", text, flags=re.MULTILINE))
